"""Audit the fixed cohort and draft six Rsubread roles without changing any catalog record."""
import argparse,gzip,hashlib,json,re,xml.etree.ElementTree as ET
from pathlib import Path
from setup_deseq2_reference import ROOT,pin,save
from collect_omics_review import paragraphs
from catalog_fixed_cohort import verify_fixed_cohort
from hifiasm_catalog import load_catalog_registry

ROLES={
 'P013':dict(summary='Used the Rsubread featureCounts function with an mm9 UCSC-gene GTF, choosing paired- or single-end settings for each sample, before combining the count tables with cbind and performing separate DESeq2 analysis.',note='The Rsubread edition and complete counting settings are unreported. Preserve the separate library declarations and feature/sample order when combining tables. R count-list and annotation behavior must be validated separately from standalone featureCounts; do not attribute DESeq2 transformations or testing to Rsubread.'),
 'P029':dict(summary='Quantified yeast gene-level reads using Rsubread featureCounts, reporting Rsubread 2.23.2 and R 4.4.1 after separate BCL Convert and DRAGEN RNA processing.',note='Retain the literal reported package and R versions. Recovery of an upstream source snapshot reporting 2.23.2 does not identify the paper binary. The reference is S. cerevisiae R64-1-1; counting options and annotation edition are unreported. DESeq2 1.48.1 remains a separate step.',version='2.23.2'),
 'P133':dict(summary='Used the Rsubread counting interface for uniquely mapped single-end RNA-seq exon-to-gene counts with junction reporting, and separately for paired-end ATAC counts over shared nonoverlapping peak regions.',note='The article spells the function featurecount, whereas the package API is featureCounts; inspect the linked code without silently repairing the source statement. RNA settings explicitly distinguish exon/gene_id meta-features, no multi-overlap or multi-mapping, unstranded single-end data, juncCounts=TRUE and genome=NULL. The ATAC statement gives isPairedEnd=TRUE and maxFragLength=100 but does not establish checkFragLength=TRUE or a countReadPairs value. Retain those omissions and do not silently enable length filtering. STAR, peak preparation, normalization and DESeq2 remain separate.',support=[40],options=dict(rna={'GTF.featureType':'exon','GTF.attrType':'gene_id','useMetaFeatures':True,'allowMultiOverlap':False,'countMultiMappingReads':False,'isLongRead':False,'ignoreDup':False,'strandSpecific':0,'juncCounts':True,'genome':None,'isPairedEnd':False,'requireBothEndsMapped':False,'checkFragLength':False,'countChimericFragments':True,'autosort':True},atac={'isPairedEnd':True,'countMultiMappingReads':False,'maxFragLength':100,'autosort':True})),
 'P139':dict(summary='Used Rsubread to load the processed paired-end RNA-seq data into R after separate STAR alignment and SAMtools sorting, indexing and deduplication, before DESeq2 testing.',note='The source does not name an Rsubread function, package edition, annotation or counting arguments. Do not infer featureCounts or claim exact paper execution from this generic loading statement. The later minimum-count filter and DESeq2 analysis are separate.'),
 'P172':dict(summary='Obtained exon read counts with Rsubread after separate STAR alignment to GRCh38; a results paragraph describes count filtering before DESeq2 analysis.',note='The Rsubread function, edition, exon-to-gene aggregation and counting options are unreported. Preserve the article\'s literal 15 bp paired-end library statement rather than rewriting it as 150 bp. Explicit feature-level and meta-feature counting controls do not identify the missing paper choice. STAR, filtering, DESeq2 and Reactome enrichment remain separate.',support=[22]),
 'P223':dict(summary='Used Rsubread featureCounts with junction-count reporting and custom GENCODE transcript annotations to extract junction reads; seqinr supplied a separate biological-sequence role.',note='Retain the custom annotation requirement, exon-junction identities and supporting counts. The source does not freeze the package edition, full counting settings or custom scripts, and its phrase featureCounts, juncCounts is not proof of a standalone juncCounts function. Salmon/edgeR expression counts and nanopore basecalling/mapping are separate workflows.')
}


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--out',type=Path,required=True);a=p.parse_args();out=a.out.resolve();assert not out.exists() and out.is_relative_to(ROOT/'build/literature-review/rsubread-runtime');out.mkdir(parents=True);data=ROOT/'docs/literature/omics-2023-2026';before={q.relative_to(ROOT).as_posix():pin(q) for q in [data/'papers.json',data/'tool-inventory.json',data/'summary.json',ROOT/'tools/literature/reviewed-uses.json']};papers=json.loads((data/'papers.json').read_bytes());verify_fixed_cohort(ROOT,data,papers);registry={q['id']:q for q in load_catalog_registry(ROOT)};reviews=json.loads((ROOT/'tools/literature/reviewed-uses.json').read_bytes())['reviews'];assert len(reviews)==1000;records=[];draft=[];census=[];observations=0
    for paper in papers:
        raw=gzip.decompress((ROOT/'build/literature-review/xml'/(paper['pmcid']+'.xml.gz')).read_bytes());assert hashlib.sha256(raw).hexdigest()==paper['xml_sha256'];xml=ET.fromstring(raw);assert next(q.text for q in xml.findall('front/article-meta/article-id') if q.get('pub-id-type')=='doi').lower()==paper['doi'].lower();ps=paragraphs(xml);by={q['paragraph_index']:q for q in ps};cache=json.loads((ROOT/'build/literature-review/extracted'/(paper['pmcid']+'.json')).read_bytes());cached={t['tool_id']:t for t in cache['tools']}
        for tool in paper['tools']:
            anchor=by[tool['evidence_paragraph_index']];assert anchor['text']==cached[tool['tool_id']]['evidence_text'] and hashlib.sha256(anchor['text'].encode()).hexdigest()==tool['evidence_paragraph_sha256'];observations+=1
        matches=[q for q in ps if re.search(registry['rsubread']['pattern'],q['match_text'],re.I)];current=[t for t in paper['tools'] if t['tool_id']=='rsubread'];assert len(current)<=1;census.append(dict(paper_id=paper['paper_id'],xml_sha256=paper['xml_sha256'],matching_paragraphs=len(matches),catalogued=bool(current)))
        if not current:assert not matches;continue
        tool=current[0];role=ROLES[paper['paper_id']];review=dict(pmcid=paper['pmcid'],doi=paper['doi'],tool_id='rsubread',evidence_paragraph_sha256=tool['evidence_paragraph_sha256'],use_summary=role['summary'],implementation_scope_note=role['note'])
        if 'version' in role:review['version_reported_near_name']=role['version']
        support=[]
        for index in role.get('support',[]):
            paragraph=by[index];assert 'rsubread' in paragraph['text'].lower();support.append(dict(paragraph_index=index,section=paragraph['section'],paragraph_sha256=hashlib.sha256(paragraph['text'].encode()).hexdigest()))
        if support:review['supporting_evidence']=support
        previous=[r for r in reviews if r['pmcid']==paper['pmcid'] and r['tool_id']=='rsubread'];assert len(previous)<=1;draft.append(dict(paper_id=paper['paper_id'],review=review));records.append(dict(paper_id=paper['paper_id'],pmcid=paper['pmcid'],doi=paper['doi'],xml_sha256=paper['xml_sha256'],primary_paragraph=tool['evidence_paragraph_index'],matching_paragraphs=matches,previous_reviews=previous,reported_options=role.get('options'),review=review))
    assert len(papers)==250 and observations==2465 and len(draft)==6 and {r['paper_id'] for r in records}==set(ROLES) and sum(bool(r['previous_reviews']) for r in records)==3;assert all(pin(ROOT/n)==v for n,v in before.items());save(out/'role-drafts.json',dict(status='six-primary-bound-Rsubread-role-drafts-only',reviews=draft));save(out/'source-audit.json',dict(status='read-only-six-Rsubread-primary-role-drafts',papers=records,source_census=census,catalog_changed=False,implementation_credit=False));save(out/'COMPLETED.json',dict(status='passed250-primary-XML-DOI-and2465-anchors-with-six-Rsubread-role-drafts-only',source_papers=250,observations=2465,roles=6,prior_roles=3,new_role_drafts=3,refined_role_drafts=3,supporting_pointers=sum(len(r['review'].get('supporting_evidence',[])) for r in draft),catalog_before=before,role_drafts=pin(out/'role-drafts.json'),source_audit=pin(out/'source-audit.json'),catalog_changed=False,implementation_credit=False,source_pins={q.relative_to(ROOT).as_posix():pin(q) for q in [Path(__file__).resolve(),ROOT/'tools/literature/collect_omics_review.py']},whole_goal_complete=False));print('Audited250 primary XML/DOIs and2465 anchors; drafted six Rsubread roles; catalog and tool count unchanged')


if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable primary-source and unchanged-catalog gates')
    main()
